type Point = [number, number];
// JSON generated by problem-owned viz/gen.py modules. Optional fields allow older exports to open.
type Data = Record<string, any>;
const numbers = (n: number, f: (i: number) => number) =>
  Array.from({ length: n }, (_, i) => f(i));
const curve = (rows: Data[] | undefined, x: string, y: string): Point[] =>
  (rows || []).map((r) => [Number(r[x]), Number(r[y])]);
const arrayCurve = (a: number[] | undefined): Point[] =>
  (a || []).map((y, x) => [x, y]);
const centers: Point[] = numbers(8, (i) => (i * Math.PI) / 4).map((x) => [
  2 * Math.cos(x),
  2 * Math.sin(x),
]);
function usePlayback() {
  const [progress, setProgress] = useState(0),
    [playing, setPlaying] = useState(false);
  useEffect(() => {
    if (!playing) return;
    let raf = 0,
      last = 0;
    const frame = (now: number) => {
      if (!last) last = now;
      const dt = Math.min(100, now - last);
      last = now;
      setProgress((t) => {
        if (t + dt / 6500 >= 1) {
          setPlaying(false);
          return 1;
        }
        return t + dt / 6500;
      });
      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [playing]);
  return { progress, setProgress, playing, setPlaying };
}
function Playback({
  p,
  label = "采样进度",
}: {
  p: ReturnType<typeof usePlayback>;
  label?: string;
}) {
  const tx = useLabText();
  return (
    <div className="playbar">
      <button
        className="icon-button"
        aria-label={p.playing ? tx("暂停动画") : tx("播放动画")}
        onClick={() => {
          if (p.progress === 1) p.setProgress(0);
          p.setPlaying(!p.playing);
        }}
      >
        {p.playing ? <Pause size={16} /> : <Play size={16} />}
      </button>
      <Slider
        label={label}
        value={p.progress}
        onChange={p.setProgress}
        step={0.001}
      />
      <button
        className="icon-button"
        aria-label={tx("重置动画")}
        onClick={() => {
          p.setProgress(0);
          p.setPlaying(false);
        }}
      >
        <RotateCcw size={16} />
      </button>
    </div>
  );
}
function useDocumentTheme() {
  const read = () => (typeof document === "undefined" ? undefined : document.documentElement.dataset.theme);
  const [theme, setTheme] = useState(read);
  useEffect(() => {
    // Canvas colors are painted once, so redraw when the app switches themes.
    const observer = new MutationObserver(() => setTheme(read()));
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
    return () => observer.disconnect();
  }, []);
  return theme;
}
function ParticleCanvas({
  points,
  field,
  ab,
  target = centers,
  comparison,
}: {
  points: Point[];
  field?: { positions: Point[]; vectors: Point[] };
  ab?: number;
  target?: Point[];
  comparison?: Point[];
}) {
  const tx = useLabText();
  const ref = useRef<HTMLCanvasElement>(null);
  const theme = useDocumentTheme();
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const ratio = window.devicePixelRatio || 1,
      w = 560,
      h = 350;
    canvas.width = w * ratio;
    canvas.height = h * ratio;
    ctx.scale(ratio, ratio);
    ctx.clearRect(0, 0, w, h);
    const light = theme === "light";
    const limit = Math.max(
      3.3,
      ...points.flat().map(Math.abs).filter(Number.isFinite),
    );
    const sx = (x: number) => w / 2 + (x / limit) * 150,
      sy = (y: number) => h / 2 - (y / limit) * 150;
    ctx.strokeStyle = light ? "#dde3eb" : "#303743";
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.moveTo(w / 2, 15);
    ctx.lineTo(w / 2, h - 15);
    ctx.moveTo(30, h / 2);
    ctx.lineTo(w - 30, h / 2);
    ctx.stroke();
    if (ab !== undefined) {
      const variance = ab * 0.15 ** 2 + 1 - ab;
      for (const [cx, cy] of target) {
        for (const scale of [1, 2]) {
          ctx.beginPath();
          ctx.ellipse(
            sx(Math.sqrt(ab) * cx),
            sy(Math.sqrt(ab) * cy),
            ((Math.sqrt(variance) * 150) / limit) * scale,
            ((Math.sqrt(variance) * 150) / limit) * scale,
            0,
            0,
            Math.PI * 2,
          );
          ctx.strokeStyle = light ? "#c4cddc55" : "#7b87992b";
          ctx.stroke();
        }
      }
    } else {
      for (const c of target) {
        ctx.beginPath();
        ctx.arc(sx(c[0]), sy(c[1]), (0.3 * 150) / limit, 0, Math.PI * 2);
        ctx.strokeStyle = light ? "#a0adbf" : "#667488";
        ctx.stroke();
      }
    }
    if (field) {
      field.positions.forEach((a, i) => {
        const v = field.vectors[i];
        if (!v || !v.every(Number.isFinite)) return;
        const norm = Math.hypot(...v) || 1,
          k = Math.min(0.14, 0.32 / norm),
          x = sx(a[0]),
          y = sy(a[1]),
          xx = sx(a[0] + v[0] * k),
          yy = sy(a[1] + v[1] * k),
          angle = Math.atan2(yy - y, xx - x);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(xx, yy);
        ctx.moveTo(
          xx - 3 * Math.cos(angle - 0.5),
          yy - 3 * Math.sin(angle - 0.5),
        );
        ctx.lineTo(xx, yy);
        ctx.lineTo(
          xx - 3 * Math.cos(angle + 0.5),
          yy - 3 * Math.sin(angle + 0.5),
        );
        ctx.strokeStyle = "#63a9a760";
        ctx.stroke();
      });
    }
    const max = window.innerWidth < 600 ? 300 : 1000;
    if (comparison) {
      ctx.fillStyle = light ? "#66758b70" : "#b2bdce70";
      comparison.slice(0, max).forEach((p) => {
        ctx.beginPath();
        ctx.arc(sx(p[0]), sy(p[1]), 2, 0, Math.PI * 2);
        ctx.fill();
      });
    }
    ctx.fillStyle = light ? "#ad7628aa" : "#c4ccdacc";
    points.slice(0, max).forEach((p) => {
      ctx.beginPath();
      ctx.arc(sx(p[0]), sy(p[1]), 2, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.fillStyle = light ? "#788698" : "#758197";
    ctx.font = "9px monospace";
    ctx.fillText("x₁", w - 35, h / 2 - 8);
    ctx.fillText("x₂", w / 2 + 8, 20);
  }, [points, field, ab, target, comparison, theme]);
  return (
    <canvas
      ref={ref}
      className="particle-canvas"
      role="img"
      aria-label={`${tx("参考解二维采样点云")} · ${points.length} ${tx("粒子")}${field ? tx("，叠加当前时间速度场") : ""}${ab !== undefined ? tx("，背景为高斯混合分量的一倍与两倍标准差等高线") : ""}`}
    />
  );
}
function Missing() {
  const tx = useLabText();
  return (
    <div className="notice">
      {tx("这道题暂未提供交互实验。你可以阅读题面并运行测试。")}
    </div>
  );
}
function GAELab({ data }: { data: Data }) {
  const tx = useLabText();
  const [gamma, setGamma] = useState(0.99),
    [lam, setLam] = useState(0.95),
    [boundaries, setBoundaries] = useState(true);
  const timeline = data.timeline || {
    rewards: numbers(20, (i) => Math.sin(i * 1.8) * 0.4 + (i === 8 ? 1 : 0)),
    values: numbers(20, (i) => Math.cos(i * 0.45) * 0.35),
    next_values: numbers(20, (i) => Math.cos((i + 1) * 0.45) * 0.35),
    terminated: numbers(20, (i) => +(i === 8)),
    truncated: numbers(20, (i) => +(i === 14)),
  };
  const r = timeline.rewards as number[],
    v = timeline.values as number[],
    next = timeline.next_values as number[],
    term = timeline.terminated as boolean[],
    trunc = timeline.truncated as boolean[];
  const delta = r.map(
    (a, i) => a + gamma * (boundaries && term[i] ? 0 : next[i]) - v[i],
  );
  const calc = (l: number) => {
    const result = Array(r.length).fill(0);
    for (let i = r.length - 1; i >= 0; i--)
      result[i] =
        delta[i] +
        gamma *
          l *
          (boundaries && (term[i] || trunc[i]) ? 0 : result[i + 1] || 0);
    return arrayCurve(result);
  };
  return (
    <>
      <Panel
        title={tx("让 TD 误差沿着时间传播")}
        description={tx(
          "拖动 γ 和 λ，观察优势估计。关闭 episode 隔离，检查误差怎样跨边界传播。",
        )}
      >
        <div className="controls">
          <Slider
            label={tx("γ · 折扣因子")}
            value={gamma}
            onChange={setGamma}
          />
          <Slider label={tx("λ · 轨迹权重")} value={lam} onChange={setLam} />
        </div>
        <Chart
          series={[arrayCurve(r), arrayCurve(v)]}
          labels={[tx("rₜ 奖励"), "V(sₜ)"]}
          xLabel={tx("时间 t")}
          yLabel="reward / value"
        />
        <div className="episode-markers">
          {r.map((_, i) => (
            <span
              key={i}
              className={term[i] ? "terminated" : trunc[i] ? "truncated" : ""}
              title={`t=${i} ${term[i] ? "terminated" : trunc[i] ? "truncated" : tx("正常步")}`}
            >
              {i}
            </span>
          ))}
        </div>
        <div className="legend">
          <span>
            <i style={{ background: "#ec8997" }} />
            terminated
          </span>
          <span>
            <i style={{ background: "#ad99d9" }} />
            truncated
          </span>
        </div>
        <Chart
          series={[calc(lam), arrayCurve(delta), calc(1)]}
          labels={[tx("Âₜ 优势"), "δₜ · λ=0", "λ = 1"]}
          xLabel={tx("时间 t")}
          yLabel="advantage"
        />
        <label className="check">
          <input
            checked={boundaries}
            type="checkbox"
            onChange={(e) => setBoundaries(e.target.checked)}
          />
          {tx("启用 episode 边界隔离")}
        </label>
        <div className="formula">
          δₜ = rₜ + γ(1 − termₜ)Vₜ₊₁ − Vₜ
          <br />
          Âₜ = δₜ + γλ(1 − doneₜ)Âₜ₊₁
        </div>
      </Panel>
      {data.bias_variance_vs_lambda ? (
        <Panel
          title={tx("偏差与方差的交换")}
          description={tx(
            "参考解在固定轨迹上的实测结果。λ 的两端体现偏差与方差之间的权衡。",
          )}
        >
          <Chart
            series={[curve(data.bias_variance_vs_lambda, "lam", "bias")]}
            labels={[tx("实测 bias")]}
            xLabel="λ"
            yLabel="bias"
          />
          <Chart
            series={[curve(data.bias_variance_vs_lambda, "lam", "variance")]}
            labels={[tx("实测 variance")]}
            xLabel="λ"
            yLabel="variance"
          />
        </Panel>
      ) : (
        <Missing />
      )}
    </>
  );
}
function RLLab({ problem, data }: { problem: Problem; data: Data }) {
  const tx = useLabText();
  const [selected, setSelected] = useState(0),
    [metric, setMetric] = useState("reward");
  if (problem.id.endsWith("/gae")) return <GAELab data={data} />;
  if (problem.id.endsWith("/ppo_clip"))
    return (
      <>
        <PPO />
        {data.trust_region ? (
          <Panel
            title={tx("同一个 batch，多轮更新后会发生什么")}
            description={tx(
              "比较参考实现与两个错误变体的 KL。下图来自同一组固定数据的真实更新。",
            )}
          >
            <Chart
              series={[
                curve(data.trust_region.reference, "epoch", "kl"),
                curve(data.trust_region.clip_only, "epoch", "kl"),
                curve(data.trust_region.max_not_min, "epoch", "kl"),
              ]}
              labels={["reference", tx("只 clip"), tx("max 替代 min")]}
              xLabel="epoch"
              yLabel="KL(old ‖ new)"
            />
            <Chart
              series={[curve(data.training, "step", "best_prob")]}
              labels={[tx("最优臂概率")]}
              xLabel="training step"
              yLabel="p(best arm)"
            />
          </Panel>
        ) : (
          <Missing />
        )}
      </>
    );
  if (problem.id.endsWith("/dpo")) {
    const d = data.t3_reward_scatter;
    return (
      <>
        <DPO />
        {data.shift_mask_grid && (
          <Panel
            title={tx("实际序列的标签移位")}
            description={tx(
              "固定 token 样本。mask 为 0 的 prompt 不参与序列 log-prob 求和。",
            )}
          >
            <div className="token-grid">
              {data.shift_mask_grid.tokens.map((token: string, i: number) => (
                <div
                  className={data.shift_mask_grid.mask[i] ? "active" : ""}
                  key={i}
                >
                  <small>{token}</small>
                  <b>{data.shift_mask_grid.mask[i]}</b>
                </div>
              ))}
            </div>
            <Chart
              series={[arrayCurve(data.shift_mask_grid.contributions)]}
              labels={[tx("有效 token log-prob")]}
              xLabel="token index"
              yLabel="contribution"
            />
          </Panel>
        )}
        {d && (
          <Panel
            title={tx("偏好学习收敛到闭式最优策略")}
            description={tx(
              "拖动训练步数，查看隐式奖励与真实奖励的关系；对照最终策略与闭式解。",
            )}
          >
            <Slider
              label={tx("训练记录")}
              value={selected}
              onChange={setSelected}
              min={0}
              max={Math.max(0, d.training.length - 1)}
              step={1}
            />
            <Chart
              series={[
                (d.training[selected]?.rewards || []).map(
                  (v: number, i: number) => [i, v],
                ),
                arrayCurve(d.true_rewards),
              ]}
              labels={[tx("隐式 rewards"), tx("真实 rewards")]}
              xLabel={tx("选项")}
              yLabel="reward"
            />
            <Chart
              series={[arrayCurve(d.policy), arrayCurve(d.optimum)]}
              labels={[tx("学到的策略"), tx("闭式最优策略")]}
              xLabel={tx("选项")}
              yLabel={tx("概率")}
            />
            <div className="metric-strip">
              <span>
                KL(π ‖ π*)<b>{Number(d.kl).toFixed(5)}</b>
              </span>
              <span>
                step<b>{d.training[selected]?.step}</b>
              </span>
            </div>
          </Panel>
        )}
      </>
    );
  }
  const dr = problem.id.endsWith("/dr_grpo"),
    curves = data.t3_length_curves;
  return (
    <>
      <GRPO dr={dr} />
      {(data.t3_reward_curve || curves) && (
        <Panel
          title={
            dr ? tx("归一化如何影响回答长度") : tx("策略更新的真实训练曲线")
          }
          description={
            dr
              ? tx(
                  "切换奖励与长度，比较 GRPO 和 Dr. GRPO。长度偏置属于展示实验，不参与通过判定。",
                )
              : tx("训练曲线来自固定随机种子的 toy 自回归策略。")
          }
        >
          <div className="segmented">
            {[
              ["reward", "Reward"],
              ["length", tx("回答长度")],
              ["wrong_length", tx("错误回答长度")],
            ].map(([v, l]) => (
              <button
                className={metric === v ? "selected" : ""}
                key={v}
                onClick={() => setMetric(v)}
              >
                {l}
              </button>
            ))}
          </div>
          <Chart
            series={
              curves
                ? [
                    curve(curves.grpo, "step", metric),
                    curve(curves.dr_grpo, "step", metric),
                  ]
                : [curve(data.t3_reward_curve, "step", metric)]
            }
            labels={curves ? ["GRPO", "Dr. GRPO"] : ["reference"]}
            xLabel="training step"
            yLabel={metric}
          />
        </Panel>
      )}
    </>
  );
}
function seededCloud() {
  let state = 42;
  const random = () => {
    state = (1664525 * state + 1013904223) >>> 0;
    return (state + 0.5) / 4294967296;
  };
  const normal = () =>
    Math.sqrt(-2 * Math.log(random())) * Math.cos(2 * Math.PI * random());
  const noise: Point[] = Array.from({ length: 500 }, () => [
    normal(),
    normal(),
  ]);
  const points: Point[] = Array.from({ length: 500 }, () => {
    const c = centers[Math.floor(random() * 8)];
    return [c[0] + 0.15 * normal(), c[1] + 0.15 * normal()];
  });
  return { noise, points };
}
function ScheduleLab({ data }: { data: Data }) {
  const tx = useLabText();
  const [time, setTime] = useState(400),
    [kind, setKind] = useState("cosine"),
    [count, setCount] = useState(1000),
    [offset, setOffset] = useState(0.008);
  const schedule = useMemo(
    () => scheduleData(kind, count, offset),
    [kind, count, offset],
  );
  const safeTime = Math.min(time, count - 1);
  const fixed = useMemo(seededCloud, []);
  const points = (data.points || fixed.points) as Point[],
    noise = (data.noise || fixed.noise) as Point[];
  const a = schedule.bars[safeTime];
  const current = points.map(
    (p, i) =>
      p.map(
        (v, j) =>
          Math.sqrt(a) * v + Math.sqrt(1 - a) * noise[i % noise.length][j],
      ) as Point,
  );
  return (
    <Panel
      title={tx("信号与噪声，在时间中的消长")}
      description={tx(
        "拖动离散时间 t，观察真实调度的累乘 ᾱₜ、log-SNR，以及固定高斯噪声下的二维点云。",
      )}
    >
      <div className="segmented">
        {["cosine", "linear"].map((v) => (
          <button
            key={v}
            className={kind === v ? "selected" : ""}
            onClick={() => setKind(v)}
          >
            {v === "cosine" ? "Cosine" : "Linear β"}
          </button>
        ))}
      </div>
      <div className="controls">
        <Slider
          label={tx("T · 调度总步数")}
          value={count}
          min={50}
          max={1000}
          step={50}
          onChange={(value) => {
            setCount(value);
            setTime((t) => Math.min(t, value - 1));
          }}
        />
        {kind === "cosine" && (
          <Slider
            label="s · cosine offset"
            value={offset}
            onChange={setOffset}
            min={0}
            max={0.05}
            step={0.001}
          />
        )}
      </div>
      <Slider
        label={tx("t · 离散时间")}
        value={safeTime}
        onChange={setTime}
        min={0}
        max={count - 1}
        step={1}
      />
      <Chart
        series={[arrayCurve(schedule.bars)]}
        labels={["ᾱₜ = ∏(1 − βₛ)"]}
        xLabel="t"
        yLabel="ᾱₜ"
      />
      <Chart
        series={[arrayCurve(schedule.bars.map((a) => Math.log(a / (1 - a))))]}
        labels={["log-SNR"]}
        xLabel="t"
        yLabel="log-SNR"
      />
      <ParticleCanvas points={current} comparison={points} ab={a} />
      <div className="legend">
        <span>{tx("灰色：固定 x₀ 与当前 xₜ")}</span>
      </div>
      <div className="metric-strip">
        <span>
          ᾱₜ <b>{a.toFixed(6)}</b>
        </span>
        <span>
          log-SNR <b>{Math.log(a / (1 - a)).toFixed(3)}</b>
        </span>
      </div>
      <div className="formula">xₜ = √ᾱₜ x₀ + √(1 − ᾱₜ) ε</div>
    </Panel>
  );
}
function DDPMLab({ data }: { data: Data }) {
  const tx = useLabText();
  const [variance, setVariance] = useState("posterior");
  const p = usePlayback(),
    entry = data.reverse_particles?.[variance],
    frames = entry?.frames as Point[][] | undefined;
  const index = Math.min(
    (frames?.length || 1) - 1,
    Math.round(p.progress * ((frames?.length || 1) - 1)),
  );
  const schedule = useMemo(() => scheduleData("linear"), []);
  const currentT = entry?.times?.[index] ?? Math.round((1 - p.progress) * 999);
  const ab = currentT < 0 ? 1 : schedule.bars[currentT];
  return (
    <>
      <Panel
        title={tx("逆着噪声，恢复八个模式")}
        description={tx(
          "播放参考解的实际采样轨迹。切换方差策略；背景圈表示当前高斯混合分量的一倍与两倍标准差轮廓。",
        )}
      >
        <div className="segmented">
          {["posterior", "beta"].map((v) => (
            <button
              key={v}
              className={variance === v ? "selected" : ""}
              onClick={() => setVariance(v)}
            >
              {v === "posterior" ? "Posterior β̃" : "Fixed β"}
            </button>
          ))}
        </div>
        <Playback p={p} />
        {frames ? (
          <ParticleCanvas
            points={frames[index]}
            target={data.centers || centers}
            ab={ab}
          />
        ) : (
          <Missing />
        )}
        <div className="metric-strip">
          <span>
            {tx("当前 t")}
            <b>{currentT}</b>
          </span>
          <span>
            variance type<b>{variance}</b>
          </span>
        </div>
      </Panel>
      <Panel
        title={tx("两种反向方差，在最后一步相遇")}
        description={tx(
          "对数纵轴下比较 βₜ 与精确后验方差 β̃ₜ；t=0 的后验方差为零，因此未画入对数曲线。",
        )}
      >
        <Chart
          series={[
            arrayCurve(data.variance_compare?.betas || schedule.betas)
              .slice(1)
              .map(([x, y]) => [x, Math.log10(y)]),
            arrayCurve(
              data.variance_compare?.posterior_variance ||
                schedule.betas.map(
                  (b, i) =>
                    (b * (1 - (i ? schedule.bars[i - 1] : 1))) /
                    (1 - schedule.bars[i]),
                ),
            )
              .slice(1)
              .map(([x, y]) => [x, Math.log10(y)]),
          ]}
          labels={["log₁₀ βₜ", "log₁₀ β̃ₜ"]}
          xLabel="t"
          yLabel="log₁₀ variance"
        />
        <div className="formula">
          β̃ₜ = βₜ (1 − ᾱₜ₋₁) / (1 − ᾱₜ)
          <br />
          {tx("t = 0：后验方差为 0，采样不添加噪声。")}
        </div>
      </Panel>
    </>
  );
}
function TrajectoryPlot({
  frames,
  labels,
}: {
  frames: Point[][][];
  labels: string[];
}) {
  const tx = useLabText();
  return (
    <svg
      className="trajectory-plot"
      viewBox="0 0 500 320"
      role="img"
      aria-label={labels.join(tx("与")) + tx(" 的粒子轨迹比较")}
    >
      {frames.map((f, k) => (
        <g
          key={k}
          fill="none"
          stroke={k ? "#98a4b7" : "#e7aa4d"}
          strokeWidth="1"
          opacity=".55"
        >
          {Array.from({ length: Math.min(30, f[0]?.length || 0) }, (_, i) => (
            <path
              key={i}
              d={f
                .map((pts, j) =>
                  pts[i]
                    ? `${j ? "L" : "M"}${250 + pts[i][0] * 45},${160 - pts[i][1] * 45}`
                    : "",
                )
                .join(" ")}
            />
          ))}
        </g>
      ))}
    </svg>
  );
}
function DDIMLab({ data }: { data: Data }) {
  const tx = useLabText();
  const [eta, setEta] = useState(0),
    [steps, setSteps] = useState(50),
    [point, setPoint] = useState(0),
    [invSteps, setInvSteps] = useState(100),
    p = usePlayback();
  const grid = (data.eta_steps_grid || []) as Data[],
    entry = grid.find((d) => d.eta === eta && d.steps === steps),
    frames = entry?.frames as Point[][] | undefined,
    index = Math.min(
      (frames?.length || 1) - 1,
      Math.round(p.progress * ((frames?.length || 1) - 1)),
    );
  const inversion = data.inversion_demo;
  const invEntry =
    inversion?.points?.find((x: Data) => x.steps === invSteps) ||
    inversion?.points?.[0];
  const picked = invEntry
    ? {
        original: invEntry.original[point],
        latent: invEntry.latent[point],
        reconstructed: invEntry.reconstructed[point],
      }
    : undefined;
  return (
    <>
      <Panel
        title={tx("η × 步数：选一条生成路径")}
        description={tx(
          "点击网格，播放该设置下由参考解预计算的真实轨迹。每格 MMD 来自独立质量评估。",
        )}
      >
        {grid.length ? (
          <>
            <div className="sampling-grid">
              {grid.map((d) => (
                <button
                  key={`${d.eta}-${d.steps}`}
                  className={d === entry ? "selected" : ""}
                  onClick={() => {
                    setEta(d.eta);
                    setSteps(d.steps);
                    p.setProgress(0);
                  }}
                >
                  <b>
                    η={d.eta} · {d.steps} {tx("步")}
                  </b>
                  <svg viewBox="0 0 100 64" aria-hidden="true">
                    {(d.samples as Point[]).slice(0, 90).map((v, i) => (
                      <circle
                        key={i}
                        cx={50 + v[0] * 10}
                        cy={32 - v[1] * 10}
                        r=".8"
                        fill="currentColor"
                      />
                    ))}
                  </svg>
                  <small>MMD² {Number(d.mmd).toFixed(4)}</small>
                </button>
              ))}
            </div>
            <Playback p={p} />
            {frames && <ParticleCanvas points={frames[index]} />}
            <div className="metric-strip">
              <span>
                η<b>{eta}</b>
              </span>
              <span>
                steps<b>{steps}</b>
              </span>
              <span>
                MMD²<b>{Number(entry?.mmd).toFixed(5)}</b>
              </span>
            </div>
          </>
        ) : (
          <Missing />
        )}
      </Panel>
      {data.trajectories && (
        <Panel
          title={tx("同样的起点，不同的随机性")}
          description={tx(
            "30 个粒子从相同 xT 出发；彩色为 η=0，灰色为 η=1 的真实轨迹。",
          )}
        >
          <TrajectoryPlot
            frames={[
              data.trajectories.deterministic,
              data.trajectories.stochastic,
            ]}
            labels={["η=0", "η=1"]}
          />
        </Panel>
      )}
      {inversion && (
        <Panel
          title={tx("反演，再生成")}
          description={tx(
            "选择数据点，查看它在噪声空间的位置和重建位置；增加步数会改变离散化误差。",
          )}
        >
          <div className="segmented">
            {inversion.steps.map((n: number) => (
              <button
                key={n}
                className={n === invSteps ? "selected" : ""}
                onClick={() => setInvSteps(n)}
              >
                {n} {tx("步")}
              </button>
            ))}
          </div>
          <div className="point-picker">
            {(invEntry?.original || []).map((_: unknown, i: number) => (
              <button
                key={i}
                className={i === point ? "selected" : ""}
                onClick={() => setPoint(i)}
              >
                {tx("点")}
                {i + 1}
              </button>
            ))}
          </div>
          {picked && (
            <>
              <Scatter
                sets={[
                  [picked.reconstructed],
                  [picked.original],
                  [picked.latent],
                ]}
                labels={[tx("重建点"), tx("原始点"), tx("反演 xT")]}
              />
              <div className="metric-strip">
                <span>
                  {tx("重建 L₂ 误差")}
                  <b>
                    {Math.hypot(
                      picked.original[0] - picked.reconstructed[0],
                      picked.original[1] - picked.reconstructed[1],
                    ).toFixed(5)}
                  </b>
                </span>
              </div>
            </>
          )}
          <Chart
            series={[
              inversion.steps.map((x: number, i: number) => [
                x,
                inversion.errors[i],
              ]),
            ]}
            labels={[tx("往返误差")]}
            xLabel="num steps"
            yLabel="round-trip error"
          />
        </Panel>
      )}
    </>
  );
}
function FlowLab({ data }: { data: Data }) {
  const tx = useLabText();
  const [reverse, setReverse] = useState(false),
    [steps, setSteps] = useState(50),
    p = usePlayback();
  const frames = data.flow_particles?.frames as Point[][] | undefined,
    index = Math.min(
      (frames?.length || 1) - 1,
      Math.round(p.progress * ((frames?.length || 1) - 1)),
    ),
    fields = data.flow_particles?.fields as Data[] | undefined,
    fieldEntry = fields?.[Math.round(p.progress * (fields.length - 1))],
    field = fieldEntry
      ? {
          positions: data.flow_particles.positions,
          vectors: fieldEntry.vectors,
        }
      : undefined;
  const compared = (data.steps_compare || []).find(
    (x: Data) => x.steps === steps,
  );
  return (
    <>
      <Panel
        title={tx("粒子沿着学到的速度场流动")}
        description={tx(
          "参考模型的实际 Euler 采样轨迹。播放或拖动 t；箭头显示同一时刻的预测速度场。",
        )}
      >
        <Playback p={p} label={tx("t · 噪声 → 数据")} />
        {frames ? (
          <ParticleCanvas points={frames[index]} field={field} />
        ) : (
          <Missing />
        )}
        <div className="formula">xₖ₊₁ = xₖ + Δt · vθ(xₖ, tₖ)　　tₖ &lt; 1</div>
      </Panel>
      {data.steps_compare && (
        <Panel
          title={tx("Euler 用多少步，分布会怎样变化")}
          description={tx(
            "切换步数，比较同一模型从相同噪声出发得到的最终样本。",
          )}
        >
          <div className="segmented">
            {data.steps_compare.map((x: Data) => (
              <button
                className={steps === x.steps ? "selected" : ""}
                key={x.steps}
                onClick={() => setSteps(x.steps)}
              >
                {x.steps} {tx("步")}
              </button>
            ))}
          </div>
          {compared && <ParticleCanvas points={compared.samples} />}
        </Panel>
      )}
      {data.convention_bug && (
        <Panel
          title={tx("同一个模型，采样方向反了")}
          description={tx(
            "切换到错误方向，查看真实 mutant 输出；训练 loss 下降并不保证采样方向正确。",
          )}
        >
          <label className="check">
            <input
              type="checkbox"
              checked={reverse}
              onChange={(e) => setReverse(e.target.checked)}
            />
            {tx("采样方向反了")}
          </label>
          <ParticleCanvas
            points={
              reverse
                ? data.convention_bug.reversed
                : data.convention_bug.correct
            }
          />
          <div className="notice">
            {reverse
              ? tx("错误：从 t=1 积分到 t=0。")
              : tx("正确：从噪声 t=0 积分到数据 t=1。")}
          </div>
        </Panel>
      )}
      {data.oracle_trajectories && (
        <Panel
          title={tx("直线与弯曲路径")}
          description={tx(
            "单点目标的最优流是直线；高斯目标的轨迹随方差变化而弯曲。下图均来自解析 oracle。",
          )}
        >
          <TrajectoryPlot
            frames={[
              data.oracle_trajectories.point,
              data.oracle_trajectories.gaussian,
            ]}
            labels={[tx("单点 oracle"), tx("高斯 oracle")]}
          />
          <div className="legend">
            <span>{tx("彩色：单点")}</span>
            <span>{tx("灰色：高斯")}</span>
          </div>
        </Panel>
      )}
      {data.loss_curve && (
        <Panel
          title={tx("为什么训练 loss 不会降到零")}
          description={tx(
            "实际 CFM 训练损失。同一个 xt 可以来自不同的样本配对，条件速度目标存在不可约方差。",
          )}
        >
          <Chart
            series={[data.loss_curve]}
            labels={["CFM training loss"]}
            xLabel="training step"
            yLabel="MSE"
          />
        </Panel>
      )}
    </>
  );
}
function ToyExperiment({ problem, report, data }: { problem: Problem; report?: Report; data: Data }) {
  const { t } = useI18n();
  const hasReference = data.kind === "toy_experiment";
  const [view, setView] = useState(hasReference ? "reference" : "yours");
  const results = report?.problem === problem.id ? report.tests.filter((test) => test.layer === "T3" && test.artifacts && Object.keys(test.artifacts).length) : [];
  const { id: _id, problem: _problem, kind: _kind, title, provenance, ...artifacts } = data;
  return <section className="toy-experiment">
    <h3>{problem.title || title}</h3>
    <p>{hasReference ? t("这是小规模核心算法实验。参考曲线由参考实现生成；你的实验结果来自运行测试时执行的代码。", "A small experiment for the core algorithm. Reference plots use the reference implementation; your results come from the code executed by Run all tests.") : t("以下曲线和指标来自你的最近一次 T3 运行。", "These curves and metrics come from your latest T3 run.")}</p>
    {provenance && <details className="toy-provenance"><summary>{t("实验出处与改编范围", "Experiment source and adaptation")}</summary><ArtifactCharts data={typeof provenance === "object" ? provenance : { provenance }} referenceRun /></details>}
    <div className="toy-view-tabs" role="group" aria-label={t("实验结果来源", "Experiment result source")}>
      {hasReference && <button aria-pressed={view === "reference"} onClick={() => setView("reference")}>{t("参考实验", "Reference experiment")}</button>}
      <button aria-pressed={view === "yours"} onClick={() => setView("yours")}>{t("我的运行结果", "My run results")}</button>
    </div>
    {view === "reference" ? <ArtifactCharts data={artifacts} referenceRun /> : results?.length ? results.map((test) => <section key={test.nodeid || test.id}><h4>{test.id} · {test.passed ? t("通过", "Passed") : t("未通过", "Failed")}</h4><ArtifactCharts data={test.artifacts!} /></section>) : <p className="notice">{t("先在编辑器完成实现并运行全部测试；T3 产生的曲线和指标会显示在这里。", "Complete your implementation and run all tests. Curves and metrics produced by T3 will appear here.")}</p>}
  </section>;
}

export default function Lab({ problem, report }: { problem: Problem; report?: Report }) {
  const tx = useLabText();
  const data = useMemo(
    () => decodeViz(problem.vizData || {}) as Data,
    [problem.vizData],
  );
  if (data.kind === "toy_experiment" || (!problem.vizData && report?.tests.some((test) => test.layer === "T3" && test.artifacts && Object.keys(test.artifacts).length))) return <ToyExperiment problem={problem} report={report} data={data} />;
  return (
    <>
      <div className="lab-heading">
        <span className="live-dot" />
        {tx("公式实验台")}
        <span>{tx("可交互 · 与判题独立")}</span>
      </div>
      {problem.id.startsWith("rl/") ? (
        <RLLab problem={problem} data={data} />
      ) : problem.id.endsWith("/schedules") ? (
        <ScheduleLab data={data} />
      ) : problem.id.endsWith("/param_conversion") ? (
        <Params />
      ) : problem.id.endsWith("/ddpm_sampling") ? (
        <DDPMLab data={data} />
      ) : problem.id.endsWith("/ddim") ? (
        <DDIMLab data={data} />
      ) : problem.id === "diffusion/flow_matching" ? (
        <FlowLab data={data} />
      ) : (
        <Missing />
      )}
    </>
  );
}
